import torch

_PARAMS = {
    (4, 4): (0.1, 0),
    (16, 32): (0.01, 10),
    (32, 64): (0.5, -20),
    (64, 128): (0.1, 0),
    (1024, 1024): (0.1, 0),
}


def gen_inputs(ctx, device):
    shape = tuple(ctx["a__shape"])
    scale, zero_point = _PARAMS.get(shape, (0.1, 0))
    fp_tensor = torch.randn(shape, device="cpu")
    q_tensor = torch.quantize_per_tensor(
        fp_tensor, scale=scale, zero_point=zero_point, dtype=torch.qint8
    ).to(device)
    return {"a": q_tensor}


def run(a):
    return torch.dequantize(a)
